117	package br.com.marealta;
118	
119	import java.sql.Connection;
120	import java.sql.DriverManager;
121	import java.sql.SQLException;
122	import java.sql.Statement;
123	
124	/** Acesso ao PostgreSQL: conexões, transações e criação do esquema. */
125	public final class Db {
126	    public interface Work<T> {
127	        T run(Connection c) throws SQLException;
128	    }
129	
130	    private final String url, user, password;
131	
132	    public Db(String url, String user, String password) {
133	        this.url = url;
134	        this.user = user;
135	        this.password = password;
136	    }
137	
138	    public <T> T tx(Work<T> work) {
139	        try (Connection c = DriverManager.getConnection(url, user, password)) {
140	            c.setAutoCommit(false);
141	            try {
142	                T result = work.run(c);
143	                c.commit();
144	                return result;
145	            } catch (Throwable t) {
146	                c.rollback();
147	                throw t;
148	            }
149	        } catch (SQLException e) {
150	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
151	        }
152	    }
153	
154	    /** Cria o que faltar; espera o banco ficar disponível (até ~60s). */
155	    public void init() {
156	        for (int attempt = 1; ; attempt++) {
157	            try {
158	                tx(c -> {
159	                    try (Statement st = c.createStatement()) {
160	                        st.execute("SELECT pg_advisory_xact_lock(7070)");
161	                        st.execute("""
162	                            CREATE TABLE IF NOT EXISTS rooms (
163	                              number INT PRIMARY KEY,
164	                              type VARCHAR(20) NOT NULL,
165	                              capacity INT NOT NULL,
166	                              nightly_rate NUMERIC(12,2) NOT NULL)""");
167	                        st.execute("""
168	                            CREATE TABLE IF NOT EXISTS reservations (
169	                              id BIGSERIAL PRIMARY KEY,
170	                              room_number INT NOT NULL REFERENCES rooms(number),
171	                              guest_name TEXT NOT NULL,
172	                              guest_email TEXT NOT NULL,
173	                              guest_cpf TEXT NOT NULL,
174	                              check_in DATE NOT NULL,
175	                              check_out DATE NOT NULL,
176	                              guests INT NOT NULL,
177	                              rate_plan VARCHAR(20) NOT NULL,
178	                              nights INT NOT NULL,
179	                              subtotal NUMERIC(12,2) NOT NULL,
180	                              discount NUMERIC(12,2) NOT NULL,
181	                              total NUMERIC(12,2) NOT NULL,
182	                              status VARCHAR(20) NOT NULL,
183	                              amount_paid NUMERIC(12,2) NOT NULL,
184	                              refund NUMERIC(12,2))""");
185	                        st.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations(room_number, check_in)");
186	                        st.execute("""
187	                            CREATE TABLE IF NOT EXISTS messages (
188	                              id BIGSERIAL PRIMARY KEY,
189	                              channel VARCHAR(20) NOT NULL,
190	                              to_addr TEXT NOT NULL,
191	                              subject TEXT NOT NULL,
192	                              body TEXT NOT NULL,
193	                              status VARCHAR(20) NOT NULL,
194	                              guest_address TEXT,
195	                              created_at TIMESTAMPTZ NOT NULL DEFAULT now())""");
196	                        st.execute("CREATE INDEX IF NOT EXISTS messages_guest_idx ON messages(guest_address, created_at)");
197	                        st.execute("""
198	                            INSERT INTO rooms(number, type, capacity, nightly_rate) VALUES
199	                              (101,'STANDARD',2,249.90),(102,'STANDARD',2,249.90),
200	                              (201,'DELUXE',3,389.90),(202,'DELUXE',3,389.90),
201	                              (301,'SUITE',4,579.90)
202	                            ON CONFLICT (number) DO NOTHING""");
203	                    }
204	                    return null;
205	                });
206	                return;
207	            } catch (RuntimeException e) {
208	                if (attempt >= 30) throw e;
209	                try {
210	                    Thread.sleep(2000);
211	                } catch (InterruptedException ie) {
212	                    Thread.currentThread().interrupt();
213	                    throw e;
214	                }
215	            }
216	        }
217	    }
218	}

