  1	package br.com.marealta.domain;
  2	
  3	import br.com.marealta.Db;
  4	import br.com.marealta.mail.Mailer;
  5	import java.math.BigDecimal;
  6	import java.sql.Connection;
  7	import java.sql.Date;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.SQLException;
 11	import java.time.LocalDate;
 12	import java.util.ArrayList;
 13	import java.util.List;
 14	
 15	public final class ReservationService {
 16	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 17	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
 18	
 19	    private static final String COLS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, "
 20	            + "rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
 21	    private static final String SUBJECT = "Reserva confirmada - Pousada Maré Alta";
 22	
 23	    private final Db db;
 24	    private final Mailer mailer;
 25	    /** Serializa as operações de escrita desta instalação (regras de disponibilidade e limites de mensagem). */
 26	    private final Object lock = new Object();
 27	
 28	    public ReservationService(Db db, Mailer mailer) {
 29	        this.db = db;
 30	        this.mailer = mailer;
 31	    }
 32	
 33	    public List<Room> rooms() {
 34	        return db.tx(c -> {
 35	            List<Room> rooms = new ArrayList<>();
 36	            try (PreparedStatement ps = c.prepareStatement(
 37	                    "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
 38	                 ResultSet rs = ps.executeQuery()) {
 39	                while (rs.next()) rooms.add(roomOf(rs));
 40	            }
 41	            return rooms;
 42	        });
 43	    }
 44	
 45	    public Reservation create(NewReservation n) {
 46	        synchronized (lock) {
 47	            return db.tx(c -> {
 48	                Room room = findRoom(c, n.roomNumber());
 49	                if (room == null) throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + n.roomNumber() + " não existe");
 50	                if (n.guests() > room.capacity()) {
 51	                    throw new ApiException(422, "CAPACITY_EXCEEDED",
 52	                            "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
 53	                }
 54	                if (isTaken(c, room.number(), n.checkIn(), n.checkOut())) {
 55	                    throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites pedidas");
 56	                }
 57	                Pricing.Quote q = Pricing.quote(room, n.checkIn(), n.checkOut(), n.ratePlan());
 58	                try (PreparedStatement ps = c.prepareStatement("INSERT INTO reservations(room_number, guest_name, guest_email, "
 59	                        + "guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
 60	                        + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',0) RETURNING " + COLS)) {
 61	                    ps.setInt(1, room.number());
 62	                    ps.setString(2, n.guestName());
 63	                    ps.setString(3, n.guestEmail());
 64	                    ps.setString(4, n.guestCpf());
 65	                    ps.setDate(5, Date.valueOf(n.checkIn()));
 66	                    ps.setDate(6, Date.valueOf(n.checkOut()));
 67	                    ps.setInt(7, n.guests());
 68	                    ps.setString(8, n.ratePlan().name());
 69	                    ps.setInt(9, q.nights());
 70	                    ps.setBigDecimal(10, q.subtotal());
 71	                    ps.setBigDecimal(11, q.discount());
 72	                    ps.setBigDecimal(12, q.total());
 73	                    try (ResultSet rs = ps.executeQuery()) {
 74	                        rs.next();
 75	                        return reservationOf(rs);
 76	                    }
 77	                }
 78	            });
 79	        }
 80	    }
 81	
 82	    public Reservation get(long id) {
 83	        return db.tx(c -> load(c, id, false));
 84	    }
 85	
 86	    public Reservation confirm(long id) {
 87	        synchronized (lock) {
 88	            return db.tx(c -> {
 89	                Reservation r = load(c, id, true);
 90	                if (r.status() != Status.PENDING) throw ApiException.notAllowed("Só é possível confirmar uma reserva pendente");
 91	                Reservation updated = r.with(Status.CONFIRMED, r.total(), null);
 92	                save(c, updated);
 93	                Room room = findRoom(c, r.roomNumber());
 94	                String receipt = Receipt.of(updated, room).toText();
 95	                String body = "Olá, " + r.guestName() + "!\n\n"
 96	                        + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
 97	                        + receipt + "\n\n"
 98	                        + "A entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!";
 99	                mailer.send(c, r.guestEmail(), SUBJECT, body);
100	                return updated;
101	            });
102	        }
103	    }
104	
105	    public Reservation cancel(long id) {
106	        synchronized (lock) {
107	            return db.tx(c -> {
108	                Reservation r = load(c, id, true);
109	                if (r.status() != Status.PENDING && r.status() != Status.CONFIRMED) {
110	                    throw ApiException.notAllowed("Só é possível cancelar antes do check-in");
111	                }
112	                BigDecimal refund = r.ratePlan() == RatePlan.STANDARD
113	                        ? r.amountPaid() : Pricing.round(BigDecimal.ZERO);
114	                Reservation updated = r.with(Status.CANCELLED, r.amountPaid(), refund);
115	                save(c, updated);
116	                return updated;
117	            });
118	        }
119	    }
120	
121	    public Reservation checkIn(long id) {
122	        synchronized (lock) {
123	            return db.tx(c -> {
124	                Reservation r = load(c, id, true);
125	                if (r.status() != Status.CONFIRMED) throw ApiException.notAllowed("Só é possível fazer check-in de uma reserva confirmada");
126	                Reservation updated = r.with(Status.CHECKED_IN, r.amountPaid(), r.refund());
127	                save(c, updated);
128	                return updated;
129	            });
130	        }
131	    }
132	
133	    public Receipt checkOut(long id) {
134	        synchronized (lock) {
135	            return db.tx(c -> {
136	                Reservation r = load(c, id, true);
