  1	package br.com.marealta.domain;
  2	
  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	
  7	/** Cálculo de preço: tudo arredondado a centavos, meio para o par, a cada passo. */
  8	public final class Pricing {
  9	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
 10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 11	
 12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
 13	
 14	    private Pricing() {}
 15	
 16	    public static BigDecimal round(BigDecimal v) {
 17	        return v.setScale(2, RoundingMode.HALF_EVEN);
 18	    }
 19	
 20	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
 21	    public static boolean isHighSeason(LocalDate night) {
 22	        int m = night.getMonthValue();
 23	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
 24	    }
 25	
 26	    public static BigDecimal nightPrice(BigDecimal nightlyRate, LocalDate night) {
 27	        return isHighSeason(night) ? round(nightlyRate.multiply(HIGH_SEASON)) : round(nightlyRate);
 28	    }
 29	
 30	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
 31	        BigDecimal subtotal = round(BigDecimal.ZERO);
 32	        int nights = 0;
 33	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
 34	            subtotal = round(subtotal.add(nightPrice(room.nightlyRate(), d)));
 35	            nights++;
 36	        }
 37	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
 38	                ? round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT)) : round(BigDecimal.ZERO);
 39	        return new Quote(nights, subtotal, discount, round(subtotal.subtract(discount)));
 40	    }
 41	}
 42	package br.com.marealta.domain;
 43	
 44	import java.math.BigDecimal;
 45	import java.text.DecimalFormat;
 46	import java.text.DecimalFormatSymbols;
 47	import java.time.LocalDate;
 48	import java.time.format.DateTimeFormatter;
 49	import java.util.Locale;
 50	
 51	/** Comprovante de reserva: dados estruturados (JSON) e texto (e-mail). */
 52	public record Receipt(String title, long reservationId, String guestName, String guestCpf, int roomNumber,
 53	                      String roomType, LocalDate checkIn, LocalDate checkOut, int nights,
 54	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
 55	
 56	    public static final String TITLE = "Comprovante de reserva";
 57	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 58	
 59	    public static Receipt of(Reservation r, Room room) {
 60	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(),
 61	                r.checkIn(), r.checkOut(), r.nights(), r.subtotal(), r.discount(), r.total());
 62	    }
 63	
 64	    public static String brl(BigDecimal v) {
 65	        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.forLanguageTag("pt-BR")));
 66	        return "R$ " + f.format(v);
 67	    }
 68	
 69	    static String formatCpf(String cpf) {
 70	        return cpf.matches("\\d{11}")
 71	                ? cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9)
 72	                : cpf;
 73	    }
 74	
