 16	    public static BigDecimal round(BigDecimal v) {
 17	        return v.setScale(2, RoundingMode.HALF_EVEN);
 18	    }
 19	
 20	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
 21	    public static boolean isHighSeason(LocalDate night) {
 22	        int m = night.getMonthValue();
 23	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
 24	    }
 25	
 26	    public static BigDecimal nightPrice(BigDecimal nightlyRate, LocalDate night) {
 27	        return isHighSeason(night) ? round(nightlyRate.multiply(HIGH_SEASON)) : round(nightlyRate);
 28	    }
