     8	import java.time.Instant;
     9	import java.util.ArrayList;
    10	import java.util.List;
    11	
    12	/** "Envia" mensagens: aplica a política e guarda o resultado na lista de mensagens. */
    13	public final class Mailer {
    14	    public static final String CHANNEL = "EMAIL";
    15	    private final MailSettings settings;
    16	    private final MessagePolicy policy;
    17	
    18	    public Mailer(MailSettings settings) {
    19	        this.settings = settings;
    20	        this.policy = new MessagePolicy(settings);
    21	    }
    22	
    23	    public void send(Connection c, String to, String subject, String body) throws SQLException {
    24	        Instant now = Instant.now();
    25	        Instant dayStart = now.atZone(settings.zone()).toLocalDate().atStartOfDay(settings.zone()).toInstant();
    26	        // Evita corrida entre mensagens para o mesmo hóspede no limite diário.
    27	        try (PreparedStatement lock = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    28	            lock.setLong(1, 7071);
    29	            lock.execute();
    30	        }
    31	        List<Outgoing> out = policy.apply(to, subject, body, now, addr -> {
    32	            try {
    33	                return sentSince(c, addr, dayStart);
    34	            } catch (SQLException e) {
    35	                throw new IllegalStateException(e);
    36	            }
    37	        });
    38	        try (PreparedStatement ps = c.prepareStatement(
    39	                "INSERT INTO messages(channel, to_addr, subject, body, status, guest_address, created_at) VALUES (?,?,?,?,?,?,?)")) {
    40	            for (Outgoing o : out) {
    41	                ps.setString(1, CHANNEL);
    42	                ps.setString(2, o.to());
    43	                ps.setString(3, o.subject());
    44	                ps.setString(4, o.body());
    45	                ps.setString(5, o.status());
    46	                ps.setString(6, o.guestAddress());
    47	                ps.setTimestamp(7, Timestamp.from(now));
    48	                ps.addBatch();
    49	            }
    50	            ps.executeBatch();
    51	        }
    52	    }
    53	
    54	    private static int sentSince(Connection c, String guestAddress, Instant since) throws SQLException {
    55	        try (PreparedStatement ps = c.prepareStatement(
    56	                "SELECT count(*) FROM messages WHERE guest_address = ? AND status = 'SENT' AND created_at >= ?")) {
    57	            ps.setString(1, guestAddress);
    58	            ps.setTimestamp(2, Timestamp.from(since));
    59	            try (ResultSet rs = ps.executeQuery()) {
    60	                rs.next();
    61	                return rs.getInt(1);
    62	            }
    63	        }
    64	    }
    65	
    66	    public static List<Message> list(Connection c) throws SQLException {
    67	        List<Message> result = new ArrayList<>();
    68	        try (PreparedStatement ps = c.prepareStatement(
    69	                "SELECT id, channel, to_addr, subject, body, status FROM messages ORDER BY id");
    70	             ResultSet rs = ps.executeQuery()) {
    71	            while (rs.next()) {
    72	                result.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4),
    73	                        rs.getString(5), rs.getString(6)));
    74	            }
    75	        }
    76	        return result;
    77	    }
    78	}
