    37	                Scope.parse(env.get("HOTEL_MAIL_VALIDATION"), d.addressValidation),
    38	                Scope.parse(env.get("HOTEL_MAIL_ARCHIVE_COPY"), d.archiveCopy),
    39	                Scope.parse(env.get("HOTEL_MAIL_QUIET_HOURS"), d.quietHours),
    40	                Scope.parse(env.get("HOTEL_MAIL_DAILY_LIMIT"), d.dailyLimit),
    41	                intOf(env.get("HOTEL_MAIL_QUIET_START"), d.quietStartHour),
    42	                intOf(env.get("HOTEL_MAIL_QUIET_END"), d.quietEndHour),
    43	                intOf(env.get("HOTEL_MAIL_DAILY_LIMIT_MAX"), d.dailyLimitMax),
    44	                env.getOrDefault("HOTEL_MAIL_ARCHIVE_ADDRESS", d.archiveAddress),
    45	                env.getOrDefault("HOTEL_MAIL_TEST_ADDRESS", d.testAddress),
