     1	package br.com.marealta.mail;
     2	
     3	import java.time.Instant;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.function.ToIntFunction;
     7	
     8	/**
     9	 * Decide o que realmente é guardado/enviado para uma mensagem desejada:
    10	 * 1) regras de bloqueio (endereço inválido, madrugada, limite diário);
    11	 * 2) redirecionamento do modo de teste;
    12	 * 3) cópia para o arquivo.
    13	 */
    14	public final class MessagePolicy {
    15	    private final MailSettings s;
    16	
    17	    public MessagePolicy(MailSettings settings) {
    18	        this.s = settings;
    19	    }
    20	
    21	    /** @param sentToday quantas mensagens já foram enviadas hoje ao endereço original dado */
    22	    public List<Outgoing> apply(String to, String subject, String body, Instant now, ToIntFunction<String> sentToday) {
    23	        List<Outgoing> out = new ArrayList<>();
    24	        if (isBlocked(to, now, sentToday)) {
    25	            out.add(new Outgoing(to, subject, body, Outgoing.BLOCKED, to));
    26	            return out;
    27	        }
    28	        String finalTo = to, finalSubject = subject, finalBody = body;
    29	        if (s.testMode()) {
    30	            finalTo = s.testAddress();
    31	            finalSubject = "[TESTE] " + subject;
    32	            finalBody = "Destinatário original: " + to + "\n" + body;
    33	        }
    34	        out.add(new Outgoing(finalTo, finalSubject, finalBody, Outgoing.SENT, to));
    35	        if (s.archiveCopy().applies(s.testMode())) {
    36	            out.add(new Outgoing(s.archiveAddress(), "[Cópia] " + finalSubject, finalBody, Outgoing.SENT, null));
    37	        }
    38	        return out;
    39	    }
    40	
    41	    private boolean isBlocked(String to, Instant now, ToIntFunction<String> sentToday) {
    42	        boolean test = s.testMode();
    43	        if (s.addressValidation().applies(test) && !isValidAddress(to)) return true;
    44	        if (s.quietHours().applies(test) && inQuietHours(now)) return true;
    45	        return s.dailyLimit().applies(test) && sentToday.applyAsInt(to) >= s.dailyLimitMax();
    46	    }
    47	
    48	    private boolean inQuietHours(Instant now) {
    49	        int h = now.atZone(s.zone()).getHour();
    50	        int a = s.quietStartHour(), b = s.quietEndHour();
    51	        return a <= b ? (h >= a && h < b) : (h >= a || h < b);
    52	    }
    53	
    54	    /** Um único @, algo antes dele e, depois, um nome com pelo menos um ponto no meio. */
    55	    public static boolean isValidAddress(String address) {
    56	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
    57	        int at = address.indexOf('@');
    58	        if (at <= 0 || at != address.lastIndexOf('@')) return false;
    59	        String domain = address.substring(at + 1);
    60	        for (int i = 1; i < domain.length() - 1; i++) {
    61	            if (domain.charAt(i) == '.') return true;
    62	        }
    63	        return false;
    64	    }
    65	}
