     1	package br.com.marealta.mail;
     2	
     3	/** Em que modo uma regra de mensagem vale. */
     4	public enum Scope {
     5	    ALWAYS, TEST_ONLY, LIVE_ONLY, OFF;
     6	
     7	    public boolean applies(boolean testMode) {
     8	        return switch (this) {
     9	            case ALWAYS -> true;
    10	            case TEST_ONLY -> testMode;
    11	            case LIVE_ONLY -> !testMode;
    12	            case OFF -> false;
    13	        };
    14	    }
    15	
    16	    static Scope parse(String raw, Scope fallback) {
    17	        if (raw == null || raw.isBlank()) return fallback;
    18	        return valueOf(raw.trim().toUpperCase());
    19	    }
    20	}

