  1	package br.com.marealta.web;
  2	
  3	import br.com.marealta.Db;
  4	import br.com.marealta.domain.ApiException;
  5	import br.com.marealta.domain.RatePlan;
  6	import br.com.marealta.domain.Receipt;
  7	import br.com.marealta.domain.Reports;
  8	import br.com.marealta.domain.Reservation;
  9	import br.com.marealta.domain.ReservationService;
 10	import br.com.marealta.domain.Room;
 11	import br.com.marealta.mail.Mailer;
 12	import br.com.marealta.mail.Message;
 13	import com.fasterxml.jackson.databind.JsonNode;
 14	import com.fasterxml.jackson.databind.ObjectMapper;
 15	import com.fasterxml.jackson.databind.node.ArrayNode;
 16	import com.fasterxml.jackson.databind.node.ObjectNode;
 17	import io.javalin.Javalin;
 18	import io.javalin.http.Context;
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeParseException;
 22	import java.util.List;
 23	import java.util.regex.Pattern;
 24	
 25	/** Rotas HTTP combinadas com o site. */
 26	public final class Api {
 27	    private static final ObjectMapper JSON = new ObjectMapper();
 28	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
 29	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
 30	
 31	    private final Db db;
 32	    private final ReservationService service;
 33	    private final Reports reports;
 34	
 35	    public Api(Db db, ReservationService service, Reports reports) {
 36	        this.db = db;
 37	        this.service = service;
 38	        this.reports = reports;
 39	    }
 40	
 41	    public Javalin build() {
 42	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 43	
 44	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 45	        app.exception(Exception.class, (e, ctx) -> {
 46	            e.printStackTrace();
 47	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 48	        });
 49	
 50	        app.get("/rooms", ctx -> {
 51	            ArrayNode arr = JSON.createArrayNode();
 52	            for (Room r : service.rooms()) {
 53	                arr.addObject().put("number", r.number()).put("type", r.type()).put("capacity", r.capacity())
 54	                   .put("nightlyRate", r.nightlyRate());
 55	            }
 56	            json(ctx, 200, arr);
 57	        });
 58	
 59	        app.post("/reservations", ctx -> json(ctx, 201, reservation(service.create(parseNew(ctx)))));
 60	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservation(service.get(id(ctx)))));
 61	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservation(service.confirm(id(ctx)))));
 62	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservation(service.cancel(id(ctx)))));
 63	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservation(service.checkIn(id(ctx)))));
 64	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, receipt(service.checkOut(id(ctx)))));
 65	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, receipt(service.document(id(ctx)))));
 66	
 67	        app.get("/messages", ctx -> {
 68	            List<Message> messages = db.tx(Mailer::list);
 69	            ArrayNode arr = JSON.createArrayNode();
 70	            for (Message m : messages) {
 71	                arr.addObject().put("id", m.id()).put("channel", m.channel()).put("to", m.to())
 72	                   .put("subject", m.subject()).put("body", m.body()).put("status", m.status());
 73	            }
 74	            json(ctx, 200, arr);
 75	        });
 76	
 77	        app.get("/reports/occupancy", ctx -> {
 78	            String raw = ctx.queryParam("date");
 79	            if (raw == null || !DATE.matcher(raw).matches()) throw ApiException.invalid("Parâmetro date deve ser AAAA-MM-DD");
 80	            csv(ctx, reports.occupancy(parseDate(raw, "date")));
 81	        });
 82	        app.get("/reports/revenue", ctx -> {
 83	            String raw = ctx.queryParam("month");
 84	            if (raw == null || !MONTH.matcher(raw).matches()) throw ApiException.invalid("Parâmetro month deve ser AAAA-MM");
 85	            try {
 86	                csv(ctx, reports.revenue(YearMonth.parse(raw)));
 87	            } catch (DateTimeParseException e) {
 88	                throw ApiException.invalid("Parâmetro month deve ser AAAA-MM");
 89	            }
 90	        });
 91	        return app;
 92	    }
 93	
 94	    // ---- entrada ----
 95	
 96	    private static long id(Context ctx) {
 97	        try {
 98	            return Long.parseLong(ctx.pathParam("id"));
 99	        } catch (NumberFormatException e) {
100	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não existe");
101	        }
102	    }
103	
104	    private static ReservationService.NewReservation parseNew(Context ctx) {
105	        JsonNode body;
106	        try {
107	            body = JSON.readTree(ctx.body());
108	        } catch (Exception e) {
109	            throw ApiException.invalid("Corpo não é um JSON válido");
110	        }
111	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo deve ser um objeto JSON");
112	
113	        int room = integer(body, "roomNumber");
114	        String name = text(body, "guestName");
115	        String email = text(body, "guestEmail");
116	        String cpf = text(body, "guestCpf");
117	        String in = text(body, "checkIn");
118	        String out = text(body, "checkOut");
119	        int guests = integer(body, "guests");
120	        String plan = text(body, "ratePlan");
121	
122	        LocalDate checkIn = parseDate(in, "checkIn");
123	        LocalDate checkOut = parseDate(out, "checkOut");
124	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
125	        if (guests < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
126	        RatePlan ratePlan;
127	        try {
128	            ratePlan = RatePlan.valueOf(plan);
129	        } catch (IllegalArgumentException e) {
130	            throw ApiException.invalid("ratePlan inválido");
131	        }
132	        return new ReservationService.NewReservation(room, name, email, cpf, checkIn, checkOut, guests, ratePlan);
133	    }
134	
135	    private static String text(JsonNode body, String field) {
136	        JsonNode n = body.get(field);
137	        if (n == null || !n.isTextual() || n.asText().isBlank()) throw ApiException.invalid("Campo obrigatório: " + field);
138	        return n.asText();
139	    }
140	
141	    private static int integer(JsonNode body, String field) {
142	        JsonNode n = body.get(field);
143	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
144	            throw ApiException.invalid("Campo obrigatório (inteiro): " + field);
145	        }
146	        return n.asInt();
147	    }
148	
149	    private static LocalDate parseDate(String raw, String field) {
150	        if (!DATE.matcher(raw).matches()) throw ApiException.invalid("Data inválida em " + field);
151	        try {
152	            return LocalDate.parse(raw);
153	        } catch (DateTimeParseException e) {
154	            throw ApiException.invalid("Data inválida em " + field);
155	        }
156	    }
157	
158	    // ---- saída ----
159	
160	    private static ObjectNode reservation(Reservation r) {
161	        ObjectNode n = JSON.createObjectNode();
162	        n.put("id", r.id()).put("roomNumber", r.roomNumber()).put("guestName", r.guestName())
163	         .put("guestEmail", r.guestEmail()).put("guestCpf", r.guestCpf())
164	         .put("checkIn", r.checkIn().toString()).put("checkOut", r.checkOut().toString())
165	         .put("guests", r.guests()).put("ratePlan", r.ratePlan().name()).put("nights", r.nights())
166	         .put("subtotal", r.subtotal()).put("discount", r.discount()).put("total", r.total())
167	         .put("status", r.status().name()).put("amountPaid", r.amountPaid());
168	        if (r.refund() == null) n.putNull("refund"); else n.put("refund", r.refund());
169	        return n;
170	    }
171	
172	    private static ObjectNode receipt(Receipt d) {
173	        ObjectNode n = JSON.createObjectNode();
174	        n.put("title", d.title()).put("reservationId", d.reservationId()).put("guestName", d.guestName())
175	         .put("guestCpf", d.guestCpf()).put("roomNumber", d.roomNumber()).put("roomType", d.roomType())
176	         .put("checkIn", d.checkIn().toString()).put("checkOut", d.checkOut().toString())
177	         .put("nights", d.nights()).put("subtotal", d.subtotal()).put("discount", d.discount())
178	         .put("total", d.total());
179	        return n;
180	    }
181	
182	    private static void json(Context ctx, int status, JsonNode node) {
183	        ctx.status(status).contentType("application/json; charset=utf-8").result(node.toString());
184	    }
185	
186	    private static void csv(Context ctx, String body) {
187	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
188	    }
189	
190	    private static void error(Context ctx, int status, String code, String message) {
191	        ObjectNode n = JSON.createObjectNode();
192	        n.put("error", code).put("message", message);
193	        json(ctx, status, n);
194	    }
195	}

