  3	import static org.junit.jupiter.api.Assertions.*;
  4	
  5	import br.com.marealta.mail.*;
  6	import java.time.Instant;
  7	import java.util.List;
  8	import org.junit.jupiter.api.Test;
  9	
 10	class MessagePolicyTest {
 11	    static final Instant NOON = Instant.parse("2027-03-10T15:00:00Z"); // 12h em São Paulo
 12	    static final Instant NIGHT = Instant.parse("2027-03-10T05:00:00Z"); // 02h em São Paulo
 13	
 14	    static MailSettings live() { return MailSettings.defaults(false); }
 15	    static MailSettings test() { return MailSettings.defaults(true); }
 16	
 17	    static List<Outgoing> run(MailSettings s, String to, Instant now, int sentToday) {
 18	        return new MessagePolicy(s).apply(to, "Assunto", "Corpo", now, a -> sentToday);
 19	    }
 20	
 21	    @Test
 22	    void addressValidation() {
 23	        assertTrue(MessagePolicy.isValidAddress("ana@gmail.com"));
 24	        assertFalse(MessagePolicy.isValidAddress("ana@gmail"));
 25	        assertFalse(MessagePolicy.isValidAddress("ana.gmail.com"));
 26	        assertFalse(MessagePolicy.isValidAddress("a@b@c.com"));
 27	        assertFalse(MessagePolicy.isValidAddress("@gmail.com"));
 28	        assertFalse(MessagePolicy.isValidAddress("ana@.com"));
 29	        assertFalse(MessagePolicy.isValidAddress("ana@gmail."));
 30	    }
 31	
 32	    @Test
 33	    void liveSendsWithArchiveCopy() {
 34	        var out = run(live(), "ana@gmail.com", NOON, 0);
 35	        assertEquals(2, out.size());
 36	        assertEquals("ana@gmail.com", out.get(0).to());
 37	        assertEquals("arquivo@pousadamarealta.com.br", out.get(1).to());
 38	        assertEquals("[Cópia] Assunto", out.get(1).subject());
 39	        assertEquals("Corpo", out.get(1).body());
 40	    }
 41	
 42	    @Test
 43	    void invalidIsBlockedWithoutCopy() {
 44	        var out = run(live(), "ana@gmail", NOON, 0);
 45	        assertEquals(1, out.size());
 46	        assertEquals("BLOCKED", out.get(0).status());
 47	        assertEquals("ana@gmail", out.get(0).to());
 48	    }
 49	
 50	    @Test
 51	    void testModeRedirects() {
 52	        var out = run(test(), "ana@gmail.com", NOON, 0);
 53	        assertEquals(1, out.size());
 54	        assertEquals("testes@pousadamarealta.com.br", out.get(0).to());
 55	        assertEquals("[TESTE] Assunto", out.get(0).subject());
 56	        assertEquals("Destinatário original: ana@gmail.com\nCorpo", out.get(0).body());
 57	        var blocked = run(test(), "ana.gmail.com", NOON, 0);
 58	        assertEquals("BLOCKED", blocked.get(0).status());
 59	        assertEquals("ana.gmail.com", blocked.get(0).to());
 60	    }
 61	
 62	    @Test
 63	    void secondInstallationWithoutArchive() {
 64	        var s = MailSettings.defaults(false);
 65	        s = new MailSettings(false, s.addressValidation(), Scope.OFF, s.quietHours(), s.dailyLimit(), 22, 7, 5,
 66	                s.archiveAddress(), s.testAddress(), s.zone());
 67	        assertEquals(1, run(s, "ana@gmail.com", NOON, 0).size());
 68	    }
 69	
 70	    @Test
 71	    void quietHoursAndLimitScopes() {
 72	        var d = live();
 73	        var s = new MailSettings(false, Scope.ALWAYS, Scope.LIVE_ONLY, Scope.LIVE_ONLY, Scope.LIVE_ONLY, 22, 7, 2,
 74	                d.archiveAddress(), d.testAddress(), d.zone());
 75	        assertEquals("BLOCKED", run(s, "ana@gmail.com", NIGHT, 0).get(0).status());
 76	        assertEquals("SENT", run(s, "ana@gmail.com", NOON, 1).get(0).status());
 77	        assertEquals("BLOCKED", run(s, "ana@gmail.com", NOON, 2).get(0).status());
 78	        var t = new MailSettings(true, Scope.ALWAYS, Scope.LIVE_ONLY, Scope.LIVE_ONLY, Scope.LIVE_ONLY, 22, 7, 2,
 79	                d.archiveAddress(), d.testAddress(), d.zone());
 80	        assertEquals("SENT", run(t, "ana@gmail.com", NIGHT, 9).get(0).status());
 81	    }
 82	
 83	    @Test
 84	    void envParsing() {
 85	        var s = MailSettings.fromEnv(java.util.Map.of("HOTEL_TEST_MODE", "true", "HOTEL_MAIL_ARCHIVE_COPY", "always"));
 86	        assertTrue(s.testMode());
 87	        assertEquals(Scope.ALWAYS, s.archiveCopy());
 88	        assertFalse(MailSettings.fromEnv(java.util.Map.of()).testMode());
 89	    }
 90	}
 91	package br.com.marealta;
 92	
 93	import static org.junit.jupiter.api.Assertions.*;
 94	
 95	import br.com.marealta.domain.Pricing;
 96	import br.com.marealta.domain.RatePlan;
 97	import br.com.marealta.domain.Receipt;
 98	import br.com.marealta.domain.Room;
 99	import java.math.BigDecimal;
100	import java.time.LocalDate;
101	import org.junit.jupiter.api.Test;
102	
103	class PricingTest {
104	    static final Room STANDARD = new Room(101, "STANDARD", 2, new BigDecimal("249.90"));
105	    static final Room DELUXE = new Room(201, "DELUXE", 3, new BigDecimal("389.90"));
106	
107	    @Test
108	    void highSeasonExample() {
109	        var q = Pricing.quote(STANDARD, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), RatePlan.STANDARD);
110	        assertEquals(2, q.nights());
111	        assertEquals(new BigDecimal("599.76"), q.total());
112	    }
113	
114	    @Test
115	    void seasonBoundaries() {
116	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 12, 14)));
117	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 12, 15)));
118	        assertTrue(Pricing.isHighSeason(LocalDate.of(2028, 2, 29)));
119	        assertFalse(Pricing.isHighSeason(LocalDate.of(2028, 3, 1)));
120	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 7, 31)));
121	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 8, 1)));
122	    }
123	
124	    @Test
125	    void nonRefundableDiscountHalfEven() {
126	        // 2 noites normais de 249,90 = 499,80; 15% = 74,97
127	        var q = Pricing.quote(STANDARD, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 3), RatePlan.NON_REFUNDABLE);
128	        assertEquals(new BigDecimal("499.80"), q.subtotal());
129	        assertEquals(new BigDecimal("74.97"), q.discount());
130	        assertEquals(new BigDecimal("424.83"), q.total());
131	        // meio exato: 0.005 -> par
132	        assertEquals(new BigDecimal("0.04"), Pricing.round(new BigDecimal("0.035")));
133	        assertEquals(new BigDecimal("0.02"), Pricing.round(new BigDecimal("0.025")));
134	    }
135	
136	    @Test
137	    void receiptText() {
138	        var q = Pricing.quote(DELUXE, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.STANDARD);
139	        var r = new Receipt(Receipt.TITLE, 7, "Carla Dias", "111.222.333-44", 201, "DELUXE",
140	                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), q.nights(), q.subtotal(), q.discount(), q.total());
141	        assertEquals("""
142	                Comprovante de reserva nº 7
143	                Hóspede: Carla Dias (CPF 111.222.333-44)
144	                Quarto: 201 (DELUXE)
145	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
146	                Diárias: R$ 779,80
147	                Total: R$ 779,80""", r.toText());
148	        assertEquals("R$ 1.234,56", Receipt.brl(new BigDecimal("1234.56")));
149	    }
150	}

